    choose: [['I\'m interested in (working / work) with a larger team.', 'working'], ['I\'d like (to know / knowing) more.', 'to know'], ['What would the job (involve / involves)?', 'involve'], ['I haven\'t decided (yet / already).', 'yet'], ['The interview is (on / at) Tuesday.', 'on'], ['It starts (at / on) ten.', 'at']],
