export const chapter4Id = (number: StoryLessonNumber) => `conversational-skills-L3-C4-${number}-${chapter4Episodes[number].skill}-ja-v1`;
export function buildCareerLesson(number: StoryLessonNumber, previous: any = {}, reference?: any) {
  const index = storyLessonNumbers.indexOf(number);
  const lesson = buildNewBeginningLesson(number, previous, 'https://api.fluentxverse.com', reference, {
    episode: chapter4Episodes[number], id: chapter4Id(number), chapterName: 'Work, Dreams & Decisions',
    setting: 'Kamo House cafe and Leo\'s bakery in Kyoto, Nao\'s ceramics orders, and a fictional Osaka design agency.',
    previousSummary: index === 0 ? 'After Chapter 3, Nao has completed her gallery exhibition, Claire is developing the cafe community, and Emma and Leo are communicating more openly.' : chapter4Episodes[requireDefined(storyLessonNumbers[index - 1], "storyLessonNumbers[index - 1]")].closing,
    storyNotes: 'Based on the supplied Chapter 4 fragment. Opening episodes A Message from Osaka and Leo\'s New Challenge are newly authored to introduce the interview and pastry brief before the supplied workshop/customer/interview/success/choice/decision episodes. Eight episodes map to Lessons 1-4 and 6-9. Use short A2-B1 language, direct character roles, natural tutor-first dialogue, Japanese support and the fixed guide/rubric. Each main character has a professional goal. Interview nextTuesday10; manager tasting nextWednesday3, friends\' preview Sunday4 with feedbackMonday evening. Workshop costs and ceramic order prices are fictional teaching figures, not market prices. Hybrid2office/3Kyoto is Emma\'s requested arrangement only; current offer remains5office. End with recruiter considering request, no approval, acceptance or move. Checkpoints5/10 remain dynamic. No new images.',
  });
  lesson.storyData.characters = [
    { id: 'emma', name: 'Emma', role: 'main', description: 'Graphic designer considering an Osaka agency role while protecting the relationships and life she has built in Kyoto.' },
    { id: 'claire', name: 'Claire', role: 'supporting', description: 'Cafe organizer planning weekly workshops and making choices within a limited budget.' },
    { id: 'leo', name: 'Leo', role: 'supporting', description: 'Baker developing a pastry for the regular menu, supportive of Emma while honest that he would miss her.' },
    { id: 'nao', name: 'Nao', role: 'supporting', description: 'Ceramic artist handling her first direct customer order after a successful gallery exhibition.' },
    { id: 'agency-team', name: 'Agency interviewer and recruiter', role: 'supporting', description: 'Staff at the fictional Osaka design agency. The recruiter can consider a hybrid-work request but has not approved it.' },
  ];
  if (number === 9) {
    const steps = lesson.missionData.tutorSteps;
    steps[1].scripts.push(
      { text: 'Now I will be the agency recruiter. Please stay as Emma. I will start the phone call.' },
      { text: '4. Hello Emma. Thank you for calling. What would you like to discuss about our offer?' },
      { text: '5. Our current offer is five office days. What arrangement would you like us to consider?' },
      { text: '6. We can consider your request, but I need to discuss it with the team. What else would you like to ask?' },
      { text: '7. We expect to reply by Monday morning, before the five p.m. reply deadline. Until then, the arrangement is not confirmed.' },
      { text: '8. Could you confirm what you understand about the status of your request?' },
    );
    steps[1].tips.unshift({ text: 'Run two short rounds. Tutor starts as Leo, then clearly announces the switch to recruiter and starts again. Keep both rounds conversational. Do not announce approval.' });
  }
  return { course: 'conversational-skills', level: 3, chapter: 4, lessonNumber: number, levelBadge: 'BEGINNER', chapterLabel: 'Chapter 4: Work, Dreams & Decisions', status: previous?.status || 'draft', overlayColor: '#17252bcc', supportLanguage: 'ja', ...lesson };
}
export function buildCareerChapter(reference?: any) {
  return storyLessonNumbers.map(number => buildCareerLesson(number, {}, reference));
}
